code.source:
#include <iostream>
#include <string>
using namespace std;

int main() {
    string first = "Goa";
    string second = " beach";
    string full = first + second;
    cout << full << endl;
    cout << full.size() << endl;
    cout << full[0] << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string line = "Goa is sunny today";
    size_t pos = line.find("sunny");
    cout << pos << endl;
    cout << line.substr(pos, 5) << endl;
    line.append("!");
    cout << line << endl;
    return 0;
}

